// THE single authorization decision point (ADR-0006). Every route, list, export, search and (later) AI retrieval
// calls `authorize` for one record or `scopeFilter` for SQL-filtered lists. Nothing else decides access.
//  - Grants are loaded once per request from scoped_assignment (active, effective now) and never cached across
//    requests, so a revocation applies to the very next request.
//  - Targets are resolved through the read models scope_node and business_unit_closure (migrations 0001/0002).
//  - Response rule: no read permission on a record -> 404 (existence not disclosed); read allowed but the action
//    denied -> 403 (see requireRead / requireAction).
import { sql, type DbOrTx, type Expression, type SqlBool } from "@mth/db";
import { PERMISSION_CODES, type Permission, type ScopeType } from "@mth/shared";
import { problems, type AuthzTracker } from "../platform/index.ts";
import {
  decide,
  scopeSets,
  type Decision,
  type DecisionContext,
  type Grant,
  type ResolvedTarget,
  type TargetLevel,
} from "./rules.ts";

export interface Principal {
  readonly kind: "user" | "service";
  readonly userId: string | null;
  /** Home organization of a user principal. */
  readonly organizationId: string | null;
  readonly grants: readonly Grant[];
  /** Request-bound counter read by the platform's fail-closed guard. */
  readonly tracker: AuthzTracker;
}

export interface TargetRef {
  readonly type: TargetLevel;
  readonly id: string;
}

const KNOWN = new Set<string>(PERMISSION_CODES);

/** Active grants of a user: not revoked, effective_from <= now < effective_to, joined with the role's permissions. */
export async function loadGrants(db: DbOrTx, userId: string): Promise<Grant[]> {
  const rows = await db
    .selectFrom("scoped_assignment as a")
    .innerJoin("role as r", "r.id", "a.role_id")
    .leftJoin("role_permission as rp", "rp.role_id", "r.id")
    .select([
      "a.id",
      "a.scope_type",
      "a.scope_id",
      "a.organization_id",
      "r.code",
      "r.inherits_downward",
      "rp.permission_code",
    ])
    .where("a.user_id", "=", userId)
    .where("a.revoked_at", "is", null)
    .where("a.effective_from", "<=", sql<Date>`now()`)
    .where((eb) => eb.or([eb("a.effective_to", "is", null), eb("a.effective_to", ">", sql<Date>`now()`)]))
    .execute();
  const byAssignment = new Map<string, { grant: Omit<Grant, "permissions">; permissions: Set<Permission> }>();
  for (const r of rows) {
    let entry = byAssignment.get(r.id);
    if (!entry) {
      entry = {
        grant: {
          assignmentId: r.id,
          roleCode: r.code,
          inheritsDownward: r.inherits_downward,
          scopeType: r.scope_type as ScopeType,
          scopeId: r.scope_id,
          organizationId: r.organization_id,
        },
        permissions: new Set(),
      };
      byAssignment.set(r.id, entry);
    }
    if (r.permission_code && KNOWN.has(r.permission_code)) entry.permissions.add(r.permission_code as Permission);
  }
  return [...byAssignment.values()].map((e) => ({ ...e.grant, permissions: e.permissions }));
}

/** Resolve a scope reference to its place in the hierarchy; null when it does not exist. */
export async function resolveTarget(db: DbOrTx, ref: TargetRef): Promise<ResolvedTarget | null> {
  const node = await db
    .selectFrom("scope_node")
    .select(["organization_id", "business_unit_id", "transformation_id"])
    .where("scope_type", "=", ref.type)
    .where("scope_id", "=", ref.id)
    .executeTakeFirst();
  if (!node) return null;
  return {
    level: ref.type,
    organizationId: node.organization_id,
    businessUnitId: node.business_unit_id,
    transformationId: node.transformation_id,
    businessUnitAncestry: node.business_unit_id ? await businessUnitAncestry(db, node.business_unit_id) : [],
  };
}

/** The BU itself followed by its ancestors (nearest first). */
export async function businessUnitAncestry(db: DbOrTx, businessUnitId: string): Promise<string[]> {
  const rows = await db
    .selectFrom("business_unit_closure")
    .select(["ancestor_id", "depth"])
    .where("descendant_id", "=", businessUnitId)
    .orderBy("depth")
    .execute();
  return rows.map((r) => r.ancestor_id);
}

/** Build a resolved target from a record the caller already loaded (saves a query). */
export async function targetFor(
  db: DbOrTx,
  level: TargetLevel,
  ids: { organizationId: string; businessUnitId?: string | null; transformationId?: string | null },
): Promise<ResolvedTarget> {
  const bu = ids.businessUnitId ?? null;
  return {
    level,
    organizationId: ids.organizationId,
    businessUnitId: bu,
    transformationId: ids.transformationId ?? null,
    businessUnitAncestry: bu ? await businessUnitAncestry(db, bu) : [],
  };
}

/** The policy function: may `principal` do `permission` on `target`? */
export async function authorize(
  db: DbOrTx,
  principal: Principal,
  permission: Permission,
  target: TargetRef | ResolvedTarget,
  context: DecisionContext = {},
): Promise<Decision & { target: ResolvedTarget | null }> {
  principal.tracker.decisions += 1;
  const resolved = "level" in target ? target : await resolveTarget(db, target);
  if (!resolved) return { allowed: false, reason: "target_not_found", viaAssignmentIds: [], target: null };
  return { ...decide(principal, permission, resolved, context), target: resolved };
}

/** Read gate: denied or missing -> 404 (never disclose existence). Returns the resolved target. */
export async function requireRead(
  db: DbOrTx,
  principal: Principal,
  permission: Permission,
  target: TargetRef | ResolvedTarget,
): Promise<ResolvedTarget> {
  const d = await authorize(db, principal, permission, target);
  if (!d.target) throw problems.notFound();
  if (!d.allowed) throw problems.notFound().withDenial(denialOf(permission, d.target));
  return d.target;
}

/** Denial details for the failed-mutation audit (denials.ts); also used by the creator-derive step (F-DG1-115). */
export function denialOf(permission: Permission, t: ResolvedTarget) {
  const recordId =
    t.level === "organization"
      ? t.organizationId
      : t.level === "business_unit"
        ? t.businessUnitId!
        : t.transformationId!;
  return {
    permission,
    recordType: t.level,
    recordId,
    organizationId: t.organizationId,
    transformationId: t.transformationId,
  };
}

/** Action gate after a successful read: denied -> 403. */
export async function requireAction(
  db: DbOrTx,
  principal: Principal,
  permission: Permission,
  target: ResolvedTarget,
  context: DecisionContext = {},
): Promise<void> {
  const d = await authorize(db, principal, permission, target, context);
  if (!d.allowed) throw problems.forbidden().withDenial(denialOf(permission, target));
}

/** True when some grant of the principal holds `permission` anywhere (catalogue reads, creating organizations). */
export function holdsAnywhere(principal: Principal, permission: Permission): boolean {
  principal.tracker.decisions += 1;
  return principal.grants.some((g) => g.permissions.has(permission));
}

/**
 * SQL scope filter for lists and search (ADR-0006): the same rules as `decide`, compiled into a WHERE expression
 * so filtering happens in the database, never after fetching. `cols` name the target row's level and hierarchy
 * columns (SQL expressions). An empty grant set yields FALSE.
 */
export function scopeFilter(
  principal: Principal,
  permission: Permission,
  cols: {
    level: Expression<string> | TargetLevel;
    organizationId: Expression<string>;
    businessUnitId?: Expression<string | null>;
    transformationId?: Expression<string | null>;
  },
): Expression<SqlBool> {
  principal.tracker.decisions += 1;
  const s = scopeSets(principal.grants, permission);
  const level = typeof cols.level === "string" ? sql<string>`${cols.level}::text` : cols.level;
  const uuids = (ids: string[]) => sql`${ids}::uuid[]`;
  const parts = [];
  if (s.orgDown.length > 0) parts.push(sql<boolean>`${cols.organizationId} = ANY(${uuids(s.orgDown)})`);
  if (s.orgExact.length > 0)
    parts.push(sql<boolean>`(${level} = 'organization' AND ${cols.organizationId} = ANY(${uuids(s.orgExact)}))`);
  if (cols.businessUnitId) {
    if (s.buExact.length > 0)
      parts.push(sql<boolean>`(${level} = 'business_unit' AND ${cols.businessUnitId} = ANY(${uuids(s.buExact)}))`);
    if (s.buDown.length > 0) {
      parts.push(
        sql<boolean>`(${level} <> 'organization' AND ${cols.businessUnitId} IN (SELECT descendant_id FROM business_unit_closure WHERE ancestor_id = ANY(${uuids(s.buDown)})))`,
      );
    }
  }
  if (cols.transformationId && s.trExact.length > 0) {
    parts.push(sql<boolean>`(${level} = 'transformation' AND ${cols.transformationId} = ANY(${uuids(s.trExact)}))`);
  }
  if (parts.length === 0) return sql<SqlBool>`FALSE`;
  return sql<SqlBool>`(${sql.join(parts, sql` OR `)})`;
}

/** Organizations in which the principal holds `permission` at any scope (listOrganizations). */
export function organizationsWith(principal: Principal, permission: Permission): string[] {
  principal.tracker.decisions += 1;
  return [...new Set(principal.grants.filter((g) => g.permissions.has(permission)).map((g) => g.organizationId))];
}
// Pure scope-resolution rules of the policy function (ADR-0006). No I/O: unit-tested exhaustively.
//
// A grant (role at scope S) applies to a target T iff
//   - S = T (same scope level and id), or
//   - S is an ancestor of T (organization -> business unit -> parent BU chain -> transformation) AND the grant
//     "applies downward" for this permission.
// A grant applies downward when its role inherits downward (TO, AUD by default) OR the permission is an
// organization-STRUCTURE permission (organization.*, business_unit.*, user.*, access.*, role.read): administering an
// organization's structure is an organization-level action, so an organization-scope grant of such a permission covers
// the organization's units, users and assignments. Business-record permissions (transformation.*, audit.read, and
// every approval permission) never cross scope boundaries without inheritance. Grants never apply across siblings,
// and a job title never implies access (grants come only from scoped_assignment).
import {
  APPROVAL_CATEGORIES,
  PERMISSIONS,
  type Permission,
  type PermissionCategory,
  type ScopeType,
} from "@mth/shared";

export interface Grant {
  readonly assignmentId: string;
  readonly roleCode: string;
  readonly inheritsDownward: boolean;
  readonly scopeType: ScopeType;
  readonly scopeId: string;
  readonly organizationId: string;
  readonly permissions: ReadonlySet<Permission>;
}

export type TargetLevel = "organization" | "business_unit" | "transformation";

/** A target with its position in the hierarchy. `businessUnitAncestry` = the BU itself then its ancestors. */
export interface ResolvedTarget {
  readonly level: TargetLevel;
  readonly organizationId: string;
  readonly businessUnitId: string | null;
  readonly transformationId: string | null;
  readonly businessUnitAncestry: readonly string[];
}

export const STRUCTURAL_PERMISSIONS: ReadonlySet<Permission> = new Set<Permission>([
  "organization.read",
  "organization.manage",
  "business_unit.read",
  "business_unit.manage",
  "user.read",
  "user.manage",
  "role.read",
  "access.read",
  "access.assign",
]);

/** Permission -> category as a Map: module source looks up runtime keys only through a Map (F-DG1-124). */
const PERMISSION_CATEGORY: ReadonlyMap<string, PermissionCategory> = new Map(Object.entries(PERMISSIONS));

export function isApprovalPermission(permission: Permission): boolean {
  const category = PERMISSION_CATEGORY.get(permission);
  return category !== undefined && APPROVAL_CATEGORIES.includes(category);
}

export function appliesDownward(grant: Grant, permission: Permission): boolean {
  return grant.inheritsDownward || STRUCTURAL_PERMISSIONS.has(permission);
}

export function grantApplies(grant: Grant, permission: Permission, target: ResolvedTarget): boolean {
  if (!grant.permissions.has(permission)) return false;
  const down = appliesDownward(grant, permission);
  switch (grant.scopeType) {
    case "organization":
      if (grant.scopeId !== target.organizationId) return false;
      return target.level === "organization" || down;
    case "business_unit":
      if (target.level === "business_unit" && target.businessUnitId === grant.scopeId) return true;
      return down && target.level !== "organization" && target.businessUnitAncestry.includes(grant.scopeId);
    case "transformation":
      return target.level === "transformation" && target.transformationId === grant.scopeId;
    default:
      // Reserved scope types (portfolio, workstream, ...) grant nothing until their stage implements them.
      return false;
  }
}

export interface Decision {
  readonly allowed: boolean;
  readonly reason: string;
  readonly viaAssignmentIds: readonly string[];
}

export interface DecisionContext {
  /** Separation-of-duties hook (ADR-0006): the requester of the item being approved. */
  readonly requesterId?: string;
}

export interface PrincipalLike {
  readonly kind: "user" | "service";
  readonly userId: string | null;
  readonly grants: readonly Grant[];
}

export function decide(
  principal: PrincipalLike,
  permission: Permission,
  target: ResolvedTarget,
  context: DecisionContext = {},
): Decision {
  if (isApprovalPermission(permission)) {
    // Automation never approves (ADR-0006, ADR-0008): a service principal cannot hold approval permissions.
    if (principal.kind === "service")
      return { allowed: false, reason: "sod.service_cannot_approve", viaAssignmentIds: [] };
    // Requester != approver.
    if (context.requesterId !== undefined && context.requesterId === principal.userId) {
      return { allowed: false, reason: "sod.requester_is_approver", viaAssignmentIds: [] };
    }
  }
  const via = principal.grants.filter((g) => grantApplies(g, permission, target)).map((g) => g.assignmentId);
  return via.length > 0
    ? { allowed: true, reason: "granted", viaAssignmentIds: via }
    : { allowed: false, reason: "no_applicable_grant", viaAssignmentIds: [] };
}

/** Grants that hold `permission`, split by how they can match in SQL (see policy.ts scopeFilter). */
export function scopeSets(grants: readonly Grant[], permission: Permission) {
  const orgExact: string[] = [];
  const orgDown: string[] = [];
  const buExact: string[] = [];
  const buDown: string[] = [];
  const trExact: string[] = [];
  for (const g of grants) {
    if (!g.permissions.has(permission)) continue;
    const down = appliesDownward(g, permission);
    if (g.scopeType === "organization") (down ? orgDown : orgExact).push(g.scopeId);
    else if (g.scopeType === "business_unit") (down ? buDown : buExact).push(g.scopeId);
    else if (g.scopeType === "transformation") trExact.push(g.scopeId);
  }
  return { orgExact, orgDown, buExact, buDown, trExact };
}
// Record-level authorization rules on top of the role permission (ADR-0020 §3). Every P2 mutation calls these through
// the access module's public interface; each one still decides through THE policy function (`authorize`), so the
// fail-closed guard counts the decision and a denial is audited (denials.ts).
//
//   *.contribute          create, and edit only rows the caller created or owns (created_by / owner_user_id)
//   action.update_own     only actions the caller owns
//   decision.decide       only the named decision owner (or a delegate acting on their behalf; workflows module)
//   evidence.review       never on evidence the caller created
//   gate.decide           only the configured approver, never the submitter (workflows module)
//   team.assign           only at the caller's transformation, and only roles WL, KDS, TD, CM, SEC
import type { DbOrTx } from "@mth/db";
import type { Permission } from "@mth/shared";
import { problems } from "../platform/index.ts";
import { authorize, denialOf, requireRead, type Principal } from "./policy.ts";
import type { ResolvedTarget } from "./rules.ts";

/** One way to be allowed to write: a permission, optionally limited to rows the caller created or owns. */
export interface WriteRule {
  readonly permission: Permission;
  /** `own`: only rows created or owned by the caller (`*.contribute`, `action.update_own`). */
  readonly scope?: "any" | "own";
}

/** Who a row belongs to, for `own` rules. On create, pass the owner the new row will have (or nothing). */
export interface Ownership {
  readonly createdBy?: string | null;
  readonly ownerUserId?: string | null;
}

/** True when the principal created or owns the row. */
export function isOwnRow(principal: Principal, row: Ownership): boolean {
  const me = principal.userId;
  if (me === null) return false;
  return row.createdBy === me || row.ownerUserId === me;
}

/**
 * The write gate for a record inside a transformation. Tries each rule in order through the policy function; an
 * `own` rule allows only when `ownership` names the caller (on create, `{ createdBy: caller }` is implied unless the
 * caller passes `strictOwner`, e.g. action.update_own requires the new action's owner to be the caller).
 * Denied -> 403 with the denial attached for the failed-mutation audit. Returns the rule that allowed it.
 */
export async function requireRecordWrite(
  db: DbOrTx,
  principal: Principal,
  target: ResolvedTarget,
  rules: readonly WriteRule[],
  ownership: Ownership,
): Promise<WriteRule> {
  if (rules.length === 0) throw new Error("requireRecordWrite: no rule");
  for (const rule of rules) {
    const d = await authorize(db, principal, rule.permission, target);
    if (!d.allowed) continue;
    if ((rule.scope ?? "any") === "any" || isOwnRow(principal, ownership)) return rule;
  }
  throw problems.forbidden().withDenial(denialOf(rules[0]!.permission, target));
}

/**
 * Read gate of a transformation-scoped record: the caller must be able to read the transformation (404 otherwise, so
 * existence is never disclosed). Returns the resolved transformation target.
 */
export function requireTransformationRead(
  db: DbOrTx,
  principal: Principal,
  transformationId: string,
): Promise<ResolvedTarget> {
  return requireRead(db, principal, "transformation.read", { type: "transformation", id: transformationId });
}

/** True when the principal holds `permission` on the target (one policy decision; nothing is thrown). */
export async function holds(
  db: DbOrTx,
  principal: Principal,
  permission: Permission,
  target: ResolvedTarget,
  requesterId?: string,
): Promise<boolean> {
  const d = await authorize(db, principal, permission, target, requesterId === undefined ? {} : { requesterId });
  return d.allowed;
}

/**
 * Acting on someone's behalf (P1 delegation table; ADR-0015 §2, ADR-0020 §3): true when `delegatorUserId` has an
 * ACTIVE, currently effective delegation to the caller that covers the record type and the target's scope. One hop
 * only - a delegate never re-delegates, so delegation cannot form a loop - and nobody delegates to themselves (CHECK).
 */
export async function actsOnBehalfOf(
  db: DbOrTx,
  principal: Principal,
  delegatorUserId: string,
  recordType: string,
  target: ResolvedTarget,
): Promise<boolean> {
  principal.tracker.decisions += 1;
  if (principal.userId === null || principal.userId === delegatorUserId) return false;
  const scopes: { type: string; id: string }[] = [
    { type: "organization", id: target.organizationId },
    ...target.businessUnitAncestry.map((id) => ({ type: "business_unit", id })),
    ...(target.transformationId ? [{ type: "transformation", id: target.transformationId }] : []),
  ];
  const rows = await db
    .selectFrom("delegation")
    .select(["scope_type", "scope_id", "record_types"])
    .where("delegator_user_id", "=", delegatorUserId)
    .where("delegate_user_id", "=", principal.userId)
    .where("organization_id", "=", target.organizationId)
    .where("status", "=", "active")
    .where("effective_from", "<=", new Date())
    .where("effective_to", ">", new Date())
    .execute();
  return rows.some(
    (d) =>
      (d.record_types === null || d.record_types.includes(recordType)) &&
      (d.scope_type === null || scopes.some((s) => s.type === d.scope_type && s.id === d.scope_id)),
  );
}
// Request-bound principal (set by the identity module's authentication hook) and the audit context derived from it.
// T-DG2-BE18 (F-DG2-440): authorisation at COMMIT time. The identity hook resolves the session and loads the grants
// once, when the request starts. A write that commits after waiting on the client (the evidence upload receives its
// body for up to requestTimeout after that) re-resolves both inside its write transaction through
// `refreshPrincipal`, which calls the identity module's own resolver (`request.reauthenticate`, the same function the
// hook uses: one source of truth). A session that ended meanwhile gives 401; the reloaded grants replace the
// request-start snapshot, so the policy then decides on the authority the caller holds at commit.
import type { DbOrTx } from "@mth/db";
import type { FastifyRequest } from "fastify";
import type { AuditContext } from "../audit/index.ts";
import { HttpProblem, problems } from "../platform/index.ts";
import type { Principal } from "./policy.ts";

/** Re-resolves the request's session and grants on `db` (a transaction); null when the session is no longer valid. */
export type PrincipalResolver = (db: DbOrTx) => Promise<Principal | null>;

declare module "fastify" {
  interface FastifyRequest {
    principal: Principal | null;
    /** Set by the identity hook together with `principal`; null for anonymous requests. */
    reauthenticate: PrincipalResolver | null;
  }
}

/** The signed-in principal, or 401. */
export function principalOf(request: FastifyRequest): Principal {
  if (!request.principal) throw problems.unauthenticated();
  return request.principal;
}

export function auditContextOf(request: FastifyRequest): AuditContext {
  const p = principalOf(request);
  return { actorUserId: p.userId, actorType: p.kind === "service" ? "service" : "user", requestId: request.id };
}

/**
 * Commit-time authorisation, step 1 (F-DG2-440): re-resolves the caller's session and reloads their grants inside
 * `tx`, and replaces `request.principal` with the result. Throws 401 `unauthenticated` (the problem the hook gives a
 * request whose session is not valid) when the session was revoked, logged out, or expired (idle or absolute), or the
 * user was disabled, after the request started. Fails closed: a request with no resolver is refused too.
 */
export async function refreshPrincipal(tx: DbOrTx, request: FastifyRequest): Promise<Principal> {
  principalOf(request);
  const resolve = request.reauthenticate;
  if (!resolve) throw problems.unauthenticated();
  const fresh = await resolve(tx);
  if (!fresh) throw problems.unauthenticated();
  request.principal = fresh;
  return fresh;
}

/**
 * Commit-time authorisation, step 2: the policy's answer on the RELOADED grants. The read gate answers 404 when the
 * caller cannot read the record (existence not disclosed), but this caller passed it when the request started and
 * already knows the record exists, so a read right that was revoked meanwhile is a refused action: 403 `forbidden`,
 * with the same denial details, so the failed-mutation audit (denials.ts) records it as `authorization.denied`.
 * Every other error is returned unchanged.
 */
export function commitTimeDenial(err: unknown): unknown {
  if (err instanceof HttpProblem && err.status === 404 && err.denial)
    return problems
      .forbidden("Your access to this record changed while the request was in progress.")
      .withDenial(err.denial);
  return err;
}

