    SensitiveRecordType:
      type: string
      enum: [benefit, business_case, evidence]
    SensitiveRecordTypePath:
      name: recordType
      in: path
      required: true
      description: "A record type that can be sensitive (ADR-0051 §2; D-195 Q3)."
      schema: { $ref: "#/components/schemas/SensitiveRecordType" }
    SensitiveRecordId:
      name: recordId
      in: path
    SensitiveRecordId:
      name: recordId
      in: path
      required: true
