    SensitiveGrantId:
      name: grantId
      in: path
      required: true
    SensitiveRecordTypeQuery:
      name: recordType
      in: query
      required: false
      schema: { $ref: "#/components/schemas/SensitiveRecordType" }
    SensitiveGrantTransformationQuery:
      name: transformationId
      in: query
      required: true
    SensitiveGrantId:
      name: grantId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    DeepLinkToken:
      name: token
      in: path
      required: true
    IfMatchOrZero:
      name: If-Match
      in: header
      required: true
      description: 'The ETag of the defaulted record being changed (ARCH-R1; the amendments of 2026-10-09 to ADR-0035, ADR-0036 and ADR-0037). `"0"` creates the row and is stale (409) once a row exists; otherwise the row version. A missing header gives 428; a stale one gives 409.'
      schema: { type: string, pattern: '^"(0|[1-9][0-9]{0,9})"$' }
    IdempotencyKey:
      name: Idempotency-Key
      in: header

