+    expect(res.headers.etag).toBe('"1"');
+    grantId = res.body.id;
+    expect(res.headers.location).toBe(`${GRANTS}/${grantId}`);
+    expect(res.body).toMatchObject({
+      status: "active",
+      version: 1,
+      granteeUserId: b.users.bo2.id,
